:root {
     --nen: #ffffff;
     --chu: #0f172a;
     --the: #f1f5f9;
     --vien: #e2e8f0;
     --nhan: #2563eb;
}

body.toi {
     --nen: #0f172a;
     --chu: #e2e8f0;
     --the: #1e293b;
     --vien: #334155;
     --nhan: #60a5fa;
}

* { box-sizing: border-box; }

body {
     margin: 0;
     padding: 28px 16px;
     font-family: Arial, "Segoe UI", sans-serif;
     background: var(--nen);
     color: var(--chu);
     transition: background 0.3s ease, color 0.3s ease;
}

.khung-bai {
     max-width: 900px;

    margin: 0 auto;
}

.thanh-dau {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 22px;
}

.thanh-dau h1 { margin: 0; font-size: 24px; }

.cong-gat {
    width: 64px;
    height: 32px;
    border-radius: 999px;
    background: var(--nhan);
    border: none;
    position: relative;
    cursor: pointer;
    padding: 0;
}

.cong-gat::after {
    content: "";
    position: absolute;
    top: 4px;
    left: 4px;
    width: 24px;
    height: 24px;
    border-radius: 50%;
    background: #ffffff;
    transition: transform 0.25s ease;
}

body.toi .cong-gat::after {
    transform: translateX(32px);
}

.the {
    background: var(--the);
    border: 1px solid var(--vien);
    border-radius: 10px;
    padding: 18px 20px;
    margin-bottom: 14px;
    transition: background 0.3s ease, border-color 0.3s ease;
}

.the h3 {
    margin: 0 0 8px;
    color: var(--nhan);
    font-size: 16px;
}

.the p {
    margin: 0;
    font-size: 14px;
    line-height: 1.7;
}

.trang-thai {
    font-size: 13px;
    opacity: 0.75;
    margin-top: 16px;
}

const nutGat = document.getElementById("nut-gat");
const trangThai = document.getElementById("trang-thai");

nutGat.addEventListener("click", () => {
  const dangToi = document.body.classList.toggle("toi");
  trangThai.textContent = dangToi
         ? "Đây là giao diện ở chế độ TỐI (đang bật)."
         : "Đây là giao diện ở chế độ SÁNG (đang bật).";
});
